  1	package com.loja.service;
  2	
  3	import com.loja.domain.*;
  4	import com.loja.dto.*;
  5	import com.loja.exception.OrderException;
  6	import com.loja.repository.*;
  7	import com.loja.state.*;
  8	import org.springframework.http.HttpStatus;
  9	import org.springframework.stereotype.Service;
 10	import org.springframework.transaction.annotation.Transactional;
 11	
 12	import java.math.BigDecimal;
 13	import java.time.Duration;
 14	import java.time.LocalDateTime;
 15	import java.util.List;
 16	import java.util.Map;
 17	import java.util.UUID;
 18	import java.util.stream.Collectors;
 19	
 20	@Service
 21	public class OrderService implements OrderStateContext {
 22	    private final OrderRepository orderRepository;
 23	    private final OrderItemRepository orderItemRepository;
 24	    private final OrderPaymentRepository orderPaymentRepository;
 25	    private final ProductRepository productRepository;
 26	    private final CustomerRepository customerRepository;
 27	    private final NotificationRepository notificationRepository;
 28	    private final CheckoutService checkoutService;
 29	    private final Map<String, OrderState> states;
 30	
 31	    public OrderService(
 32	            OrderRepository orderRepository,
 33	            OrderItemRepository orderItemRepository,
 34	            OrderPaymentRepository orderPaymentRepository,
 35	            ProductRepository productRepository,
 36	            CustomerRepository customerRepository,
 37	            NotificationRepository notificationRepository,
 38	            CheckoutService checkoutService,
 39	            List<OrderState> stateList) {
 40	        this.orderRepository = orderRepository;
 41	        this.orderItemRepository = orderItemRepository;
 42	        this.orderPaymentRepository = orderPaymentRepository;
 43	        this.productRepository = productRepository;
 44	        this.customerRepository = customerRepository;
 45	        this.notificationRepository = notificationRepository;
 46	        this.checkoutService = checkoutService;
 47	        this.states = stateList.stream().collect(Collectors.toMap(OrderState::getStatusCode, s -> s));
 48	    }
 49	
 50	    @Transactional
 51	    public OrderResponse createOrder(CheckoutRequest request) {
 52	        SummaryResponse summary = checkoutService.calculateSummary(request);
 53	
 54	        Customer customer = customerRepository.findById(request.getCustomer().getCpf())
 55	            .orElse(new Customer(request.getCustomer().getCpf(),
 56	                               request.getCustomer().getEmail(),
 57	                               request.getClubTier()));
 58	        customerRepository.save(customer);
 59	
 60	        String orderId = UUID.randomUUID().toString();
 61	
 62	        Order order = new Order();
 63	        order.setId(orderId);
 64	        order.setCustomerCpf(request.getCustomer().getCpf());
 65	        order.setCustomerEmail(request.getCustomer().getEmail());
 66	        order.setStatus("AWAITING_PAYMENT");
 67	        order.setZipCode(request.getZipCode());
 68	        order.setRegion(request.getRegion());
 69	        order.setShippingMethod(request.getShippingMethod());
 70	        order.setCoupon(request.getCoupon());
 71	        order.setPaymentMethod(request.getPaymentMethod());
 72	        order.setInstallments(request.getInstallments() != null ? request.getInstallments() : 1);
 73	        order.setClubTier(request.getClubTier());
 74	
 75	        order.setProductsSubtotal(summary.getProductsSubtotal());
 76	        order.setCouponDiscount(summary.getCouponDiscount());
 77	        order.setShippingCost(summary.getShippingCost());
 78	        order.setDeliveryDays(summary.getDeliveryDays());
 79	        order.setInsurance(summary.getInsurance());
 80	        order.setPaymentAdjustment(summary.getPaymentAdjustment());
 81	        order.setFinalTotal(summary.getFinalTotal());
 82	        order.setInstallmentAmount(summary.getInstallmentAmount());
 83	        order.setNextPurchaseCredit(summary.getNextPurchaseCredit());
 84	        order.setGift(summary.getGift());
 85	
 86	        order.setCreatedAt(LocalDateTime.now());
 87	
 88	        orderRepository.save(order);
 89	
 90	        for (var item : request.getItems()) {
 91	            orderItemRepository.save(new OrderItem(orderId, item.getSku(), item.getQuantity()));
 92	        }
 93	
 94	        return toOrderResponse(order, request.getItems());
 95	    }
 96	
 97	    @Transactional(readOnly = true)
 98	    public OrderResponse getOrder(String id) {
 99	        Order order = orderRepository.findById(id)
100	            .orElseThrow(() -> new OrderException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
101	
102	        List<OrderItem> items = orderItemRepository.findByOrderId(id);
103	        List<ItemRequest> itemRequests = items.stream()
104	            .map(item -> {
105	                ItemRequest ir = new ItemRequest();
106	                ir.setSku(item.getSku());
107	                ir.setQuantity(item.getQuantity());
108	                return ir;
109	            })
110	            .collect(Collectors.toList());
111	
112	        return toOrderResponse(order, itemRequests);
113	    }
114	
115	    @Transactional
116	    public OrderResponse processPayment(String orderId, PaymentRequest paymentRequest) {
117	        if (paymentRequest.getTransactionId() == null || paymentRequest.getPaidAt() == null) {
118	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
119	        }
120	
121	        Order order = orderRepository.findById(orderId)
122	            .orElseThrow(() -> new OrderException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
123	
124	        OrderState state = states.get(order.getStatus());
125	        order.setState(state);
126	
127	        state.handlePayment(order, paymentRequest, this);
128	
129	        List<OrderItem> items = orderItemRepository.findByOrderId(orderId);
130	        List<ItemRequest> itemRequests = items.stream()
131	            .map(item -> {
132	                ItemRequest ir = new ItemRequest();
133	                ir.setSku(item.getSku());
134	                ir.setQuantity(item.getQuantity());
135	                return ir;
136	            })
137	            .collect(Collectors.toList());
138	
139	        return toOrderResponse(order, itemRequests);
140	    }
141	
142	    @Transactional
143	    public OrderResponse shipOrder(String orderId, ShipmentRequest shipmentRequest) {
144	        if (shipmentRequest.getTrackingCode() == null) {
145	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
146	        }
147	
148	        Order order = orderRepository.findById(orderId)
149	            .orElseThrow(() -> new OrderException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
150	
151	        OrderState state = states.get(order.getStatus());
152	        order.setState(state);
153	
154	        state.handleShipment(order, shipmentRequest, this);
155	
156	        List<OrderItem> items = orderItemRepository.findByOrderId(orderId);
157	        List<ItemRequest> itemRequests = items.stream()
158	            .map(item -> {
159	                ItemRequest ir = new ItemRequest();
160	                ir.setSku(item.getSku());
161	                ir.setQuantity(item.getQuantity());
162	                return ir;
163	            })
164	            .collect(Collectors.toList());
165	
166	        return toOrderResponse(order, itemRequests);
167	    }
168	
169	    @Transactional
170	    public OrderResponse deliverOrder(String orderId) {
171	        Order order = orderRepository.findById(orderId)
172	            .orElseThrow(() -> new OrderException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
173	
174	        OrderState state = states.get(order.getStatus());
175	        order.setState(state);
176	
177	        state.handleDelivery(order, this);
178	
179	        List<OrderItem> items = orderItemRepository.findByOrderId(orderId);
180	        List<ItemRequest> itemRequests = items.stream()
181	            .map(item -> {
182	                ItemRequest ir = new ItemRequest();
183	                ir.setSku(item.getSku());
184	                ir.setQuantity(item.getQuantity());
185	                return ir;
186	            })
187	            .collect(Collectors.toList());
188	
189	        return toOrderResponse(order, itemRequests);
190	    }
191	
192	    @Transactional
193	    public OrderResponse cancelOrder(String orderId) {
194	        Order order = orderRepository.findById(orderId)
195	            .orElseThrow(() -> new OrderException("ORDER_NOT_FOUND", HttpStatus.NOT_FOUND));
196	
197	        OrderState state = states.get(order.getStatus());
198	        order.setState(state);
199	
200	        state.handleCancellation(order, this);
201	
202	        List<OrderItem> items = orderItemRepository.findByOrderId(orderId);
203	        List<ItemRequest> itemRequests = items.stream()
204	            .map(item -> {
205	                ItemRequest ir = new ItemRequest();
206	                ir.setSku(item.getSku());
207	                ir.setQuantity(item.getQuantity());
208	                return ir;
209	            })
210	            .collect(Collectors.toList());
211	
212	        return toOrderResponse(order, itemRequests);
213	    }
214	
215	    @Override
216	    public void saveOrder(Order order) {
217	        orderRepository.save(order);
218	    }
219	
220	    @Override
221	    public void reserveStock(Order order) {
222	        List<OrderItem> items = orderItemRepository.findByOrderId(order.getId());
223	
224	        for (OrderItem item : items) {
225	            Product product = productRepository.findBySkuForUpdate(item.getSku())
226	                .orElseThrow(() -> new RuntimeException("Product not found"));
227	
228	            if (product.getStock() < item.getQuantity()) {
229	                throw new RuntimeException("Insufficient stock");
230	            }
231	
232	            product.setStock(product.getStock() - item.getQuantity());
233	            productRepository.save(product);
234	        }
235	    }
236	
237	    @Override
238	    public void releaseStock(Order order) {
239	        List<OrderItem> items = orderItemRepository.findByOrderId(order.getId());
240	
241	        for (OrderItem item : items) {
242	            Product product = productRepository.findBySkuForUpdate(item.getSku())
243	                .orElseThrow(() -> new RuntimeException("Product not found"));
244	
245	            product.setStock(product.getStock() + item.getQuantity());
246	            productRepository.save(product);
247	        }
248	    }
249	
250	    @Override
251	    public void addCredit(String cpf, BigDecimal amount) {
252	        if (amount.compareTo(BigDecimal.ZERO) == 0) {
253	            return;
254	        }
255	
256	        Customer customer = customerRepository.findByCpfForUpdate(cpf)
257	            .orElseThrow(() -> new RuntimeException("Customer not found"));
258	
259	        customer.setCreditBalance(customer.getCreditBalance().add(amount));
260	        customerRepository.save(customer);
261	    }
262	
263	    @Override
264	    public void removeCredit(String cpf, BigDecimal amount) {
265	        if (amount.compareTo(BigDecimal.ZERO) == 0) {
266	            return;
267	        }
268	
269	        Customer customer = customerRepository.findByCpfForUpdate(cpf)
270	            .orElseThrow(() -> new RuntimeException("Customer not found"));
271	
272	        customer.setCreditBalance(customer.getCreditBalance().subtract(amount));
273	        customerRepository.save(customer);
274	    }
